&lt;ul data-path-to-node=&quot;17&quot;&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;17,0,0&quot;&gt;&lt;strong data-path-to-node=&quot;17,0,0&quot; data-index-in-node=&quot;0&quot;&gt;Outillage Pentest / Red Team :&lt;/strong&gt; Burp Suite Pro, C2 Frameworks (Sliver, Havoc, Adaptix), Metasploit, BloodHound.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;17,1,0&quot;&gt;&lt;strong data-path-to-node=&quot;17,1,0&quot; data-index-in-node=&quot;0&quot;&gt;Environnements Cloud &amp;amp; Infra :&lt;/strong&gt; AWS, GCP, Azure, Active Directory / Entra ID, Docker/Kubernetes.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;17,2,0&quot;&gt;&lt;strong data-path-to-node=&quot;17,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Langages :&lt;/strong&gt; Python, Go, Bash, PowerShell.&lt;/p&gt;
&lt;/li&gt;
