&lt;/ul&gt;
&lt;h3 data-section-id=&quot;h3s27h&quot; data-start=&quot;3289&quot; data-end=&quot;3317&quot;&gt;&lt;strong data-start=&quot;3293&quot; data-end=&quot;3317&quot;&gt;Preferred Background&lt;/strong&gt;&lt;/h3&gt;
